/* =========================================================
   IMORY SANDBOX — 저자 JS fixture (SANDBOX-5A)

   진단용이다. 미관이 목적이 아니라, 지시문 9절의 네 가지가
   프레임 안에서 실제로 도는지 e2e 가 숫자로 셀 수 있게 하는 것이
   목적이다. 외부 라이브러리도 외부 네트워크도 쓰지 않는다.

   남기는 표식(렌더 루트의 data-*):
     data-imory-authorjs-runs    이 realm 에서 이 코드가 돈 횟수
     data-imory-authorjs-page    imorySkin.pageType
     data-imory-authorjs-api     imorySkin.version
     data-imory-authorjs-clicks  패널 토글을 누른 횟수
     data-imory-authorjs-frames  rAF 프레임 수
     data-imory-authorjs-ticks   setInterval 이 돈 횟수
     data-imory-authorjs-drag    드래그로 옮긴 좌표
     data-imory-authorjs-nav     navigate() 결과
     data-imory-authorjs-badnav  표에 없는 주소로 navigate() 한 결과
========================================================== */

(function () {

  var api =
    window.imorySkin;

  var root =
    api && api.root
      ? api.root
      : document.getElementById("sandboxFrameRoot");

  if (!root) {
    return;
  }


  /* --- 표식: 이 realm 에서 몇 번 돌았는가 ---------------- */

  var runs =
    Number(root.getAttribute("data-imory-authorjs-runs") || "0") + 1;

  root.setAttribute("data-imory-authorjs-runs", String(runs));

  root.setAttribute(
    "data-imory-authorjs-page",
    api && typeof api.pageType === "string" ? api.pageType : ""
  );

  root.setAttribute(
    "data-imory-authorjs-api",
    api ? String(api.version) : "0"
  );


  /* --- 1. 버튼 클릭으로 패널 열기/닫기 ------------------- */

  var toggle =
    root.querySelector(".sb-js-toggle");

  var panel =
    root.querySelector(".sb-js-panel");

  var clicks =
    0;

  if (toggle && panel) {

    /*
      ★ 초기 상태는 **코드가** 세운다.

      스킨 HTML 에 data-open="0" 을 적어 둬도 sanitizer 가 지운다 —
      허용 속성은 class/lang/dir/title/role 과 data-imory-* 뿐이다
      (skin/skin-sanitize.js). 저자가 자기 상태 속성을 쓰려면 이렇게
      JS 로 세워야 한다.
    */

    panel.setAttribute("data-open", "0");

    toggle.addEventListener("click", function () {

      clicks += 1;

      var open =
        panel.getAttribute("data-open") === "1";

      panel.setAttribute("data-open", open ? "0" : "1");

      root.setAttribute("data-imory-authorjs-clicks", String(clicks));

    });

  }


  /* --- 2. 파티클 (rAF) ----------------------------------- */

  var field =
    root.querySelector(".sb-js-particles");

  var dots =
    [];

  var frames =
    0;

  var rafId =
    0;

  if (field) {

    for (var i = 0; i < 12; i += 1) {

      var dot =
        document.createElement("span");

      dot.className = "sb-js-dot";

      field.appendChild(dot);

      dots.push({
        el: dot,
        x: (i * 13) % 100,
        y: (i * 29) % 90,
        vx: 0.35 + (i % 3) * 0.12
      });

    }


    var step = function () {

      frames += 1;

      for (var j = 0; j < dots.length; j += 1) {

        var d = dots[j];

        d.x = (d.x + d.vx) % 100;

        /* CSSOM 쓰기다 — style 속성 문자열을 넣지 않는다 */

        d.el.style.left = d.x.toFixed(2) + "%";
        d.el.style.top = d.y.toFixed(2) + "%";

      }

      root.setAttribute("data-imory-authorjs-frames", String(frames));

      rafId = window.requestAnimationFrame(step);

    };

    rafId = window.requestAnimationFrame(step);

  }


  /* --- 3. 드래그 가능한 카드 ----------------------------- */

  var card =
    root.querySelector(".sb-js-card");

  var dragging = false;
  var startX = 0;
  var startY = 0;
  var offsetX = 0;
  var offsetY = 0;

  var onMove = function (event) {

    if (!dragging || !card) {
      return;
    }

    var nx = offsetX + (event.clientX - startX);
    var ny = offsetY + (event.clientY - startY);

    card.style.transform = "translate(" + nx + "px, " + ny + "px)";

    root.setAttribute(
      "data-imory-authorjs-drag",
      Math.round(nx) + "," + Math.round(ny)
    );

  };

  var onUp = function (event) {

    if (!dragging) {
      return;
    }

    dragging = false;

    offsetX = offsetX + (event.clientX - startX);
    offsetY = offsetY + (event.clientY - startY);

  };

  if (card) {

    card.addEventListener("pointerdown", function (event) {

      dragging = true;

      startX = event.clientX;
      startY = event.clientY;

      event.preventDefault();

    });

    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);

  }


  /* --- 4. 타이머 표식 ------------------------------------ */

  /*
    ticks 는 이 코드가 만든 타이머 **한 벌**이 돈 횟수이고,
    window.__imoryFixtureTicks 는 이 realm 의 **모든** 벌이 돈
    횟수다. 같은 realm 에서 두 번 실행되면 두 값이 갈라진다 —
    e2e 가 그 차이로 중복을 판정한다.
  */

  var ticks =
    0;

  var timer =
    window.setInterval(function () {

      ticks += 1;

      window.__imoryFixtureTicks =
        (window.__imoryFixtureTicks || 0) + 1;

      root.setAttribute("data-imory-authorjs-ticks", String(ticks));

    }, 100);


  /* --- navigate() — 부모가 발급한 표에 있는 주소만 -------- */

  var go =
    root.querySelector(".sb-js-go");

  if (go && api) {

    var categories =
      api.context &&
      api.context.navigation &&
      api.context.navigation.categories;

    var href =
      categories && categories[0] && categories[0].href
        ? categories[0].href
        : "";

    go.setAttribute("data-imory-authorjs-target", href);

    go.addEventListener("click", function () {

      root.setAttribute(
        "data-imory-authorjs-nav",
        api.navigate(href) ? "1" : "0"
      );

    });

  }


  var bad =
    root.querySelector(".sb-js-badnav");

  if (bad && api) {

    bad.addEventListener("click", function () {

      root.setAttribute(
        "data-imory-authorjs-badnav",
        api.navigate("https://example.com/evil") ? "1" : "0"
      );

    });

  }


  /* --- 정리 지점 ----------------------------------------- */

  if (api && typeof api.onCleanup === "function") {

    api.onCleanup(function () {

      window.clearInterval(timer);

      if (rafId) {
        window.cancelAnimationFrame(rafId);
      }

      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);

    });

  }

}());
